final class AICS_SEO_Plugin_Detector{private static ?array $cache=null;public function active():array{if(null!==self::$cache){return self::$cache;}$a=array();if(defined('WPSEO_VERSION')||class_exists('WPSEO_Options')){$a[]='yoast';}if(defined('RANK_MATH_VERSION')||class_exists('RankMath')){$a[]='rank_math';}if(defined('AIOSEO_VERSION')||(function_exists('aioseo')&&class_exists('AIOSEO\\Plugin\\Common\\Models\\Post'))){$a[]='aioseo';}return self::$cache=$a;}public function resolve(string $requested='auto'):array{$requested=sanitize_key($requested);if(!in_array($requested,array('auto','native','yoast','rank_math','aioseo'),true)){$requested='auto';}$active=$this->active();$available='native'===$requested||'auto'===$requested||in_array($requested,$active,true);$key='auto'===$requested?($active[0]??'native'):$requested;return array('key'=>$key,'requested'=>$requested,'available'=>$available,'active'=>$active,'multiple'=>count($active)>1,'warning'=>count($active)>1?'multiple_seo_plugins_active':'','error'=>$available?'':'seo_target_plugin_unavailable');}}
